const input = $input.first().json;

const query = String(input['Business category'] ?? input.query ?? '').trim();
const city = String(input['City'] ?? input.city ?? '').trim();
const country = String(input['Country code'] ?? input.country ?? '').trim().toUpperCase();
const targetLeads = Number(input['Number of leads'] ?? input.target_leads);

if (!query) throw new Error('Enter a business category, for example "dentist".');
if (!city) throw new Error('Enter a city, for example "Manchester".');
if (!/^[A-Z]{2}$/.test(country)) {
  throw new Error('Country must be a two-letter ISO code, for example GB, US or TR.');
}
if (!Number.isInteger(targetLeads) || targetLeads < 1 || targetLeads > 500) {
  throw new Error('Number of leads must be a whole number between 1 and 500.');
}

return [{ json: { query, city, country, target_leads: targetLeads } }];

// A BasedOnBusiness job object arrives here, either straight from the submit
// call or from the most recent status poll.
const job = $input.first().json;
const status = String(job.status ?? '').toLowerCase();

if (status === 'done') return [{ json: job }];

if (status === 'failed' || status === 'cancelled') {
  throw new Error('BasedOnBusiness search ended with status "' + status + '"' + (job.error ? ': ' + job.error : '') + '.');
}

// pending / submitted / running mean the job is still being collected.
if (!['pending', 'submitted', 'running'].includes(status)) {
  throw new Error('Unexpected BasedOnBusiness status: ' + (status || 'missing') + '.');
}

// Wall-clock guard, so a stuck job can never loop forever.
const createdAt = Date.parse(job.created_at ?? '');
if (!Number.isFinite(createdAt)) {
  throw new Error('BasedOnBusiness response did not include a valid created_at timestamp.');
}
if (Date.now() - createdAt >= 15 * 60 * 1000) {
  throw new Error('BasedOnBusiness search did not finish within 15 minutes. Job id: ' + job.id);
}

return [{ json: job }];

const search = $('Prepare Search').first().json;

return $input.all().map(({ json }) => {
  const mapsQuery = [json.title, json.address].filter(Boolean).join(', ');
  let mapsUrl = '';
  if (mapsQuery) {
    mapsUrl = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(mapsQuery);
    // place_id pins the link to the exact listing instead of a text search.
    if (json.place_id) mapsUrl += '&query_place_id=' + encodeURIComponent(json.place_id);
  }

  return {
    json: {
      'Business Name': json.title ?? '',
      'Phone': json.phone ?? '',
      'Address': json.address ?? '',
      'Category': json.category ?? '',
      'Rating': json.rating ?? '',
      'Reviews': json.reviews_count ?? 0,
      'Google Maps URL': mapsUrl,
      'City': search.city ?? '',
      'Country': search.country ?? ''
    }
  };
});
